class BankAccount:
    def __init__(self, owner: str, initial_balance: float = 0.0):
        self.owner = owner
        self.balance = initial_balance

    def deposit(self, amount: float) -> None:
        if amount <= 0:
            raise ValueError('Deposit must be positive')
        self.balance += amount

acc = BankAccount('Dev', 100.0)
acc.deposit(50.0)
print(f'{acc.owner}: ${acc.balance:.2f}')

class Temperature:
    def __init__(self, celsius: float):
        self._celsius = celsius

    @property
    def celsius(self) -> float:
        return self._celsius

    @celsius.setter
    def celsius(self, value: float) -> None:
        if value < -273.15:
            raise ValueError('Below absolute zero')
        self._celsius = value

t = Temperature(25.0)
t.celsius = 30.0
print(f'Current temp: {t.celsius} C')

class Employee:
    def __init__(self, name: str, salary: float):
        self.name = name
        self.salary = salary

    def compensation(self) -> float:
        return self.salary

class Manager(Employee):
    def __init__(self, name: str, salary: float, bonus: float):
        super().__init__(name, salary)
        self.bonus = bonus

    def compensation(self) -> float:
        return self.salary + self.bonus

mgr = Manager('Amina', 120000.0, 20000.0)
print(f'{mgr.name} compensation: ${mgr.compensation():.2f}')

class ConsoleLogger:
    def log(self, msg: str) -> None:
        print(f'[LOG] {msg}')

class OrderProcessor:
    def __init__(self, logger):
        self.logger = logger  # Composition

    def process_order(self, order_id: int) -> None:
        self.logger.log(f'Processing order {order_id}')

processor = OrderProcessor(ConsoleLogger())
processor.process_order(101)

class Point:
    def __init__(self, x: int, y: int):
        self.x = x
        self.y = y

    def __repr__(self) -> str:
        return f'Point({self.x}, {self.y})'

    def __eq__(self, other) -> bool:
        if not isinstance(other, Point):
            return False
        return self.x == other.x and self.y == other.y

p1 = Point(3, 4)
p2 = Point(3, 4)
print(repr(p1))
print(p1 == p2)

class Stack:
    def __init__(self):
        self._items = []
    def push(self, val):
        self._items.append(val)
    def pop(self):
        return self._items.pop()
    def __len__(self):
        return len(self._items)

s = Stack()
s.push(10); s.push(20)
print(f'Length: {len(s)}, Popped: {s.pop()}')
